css:
.list {
  display: grid;
  grid-template-columns: repeat(3, auto);
  justify-items: start;   /* each item at the left of its cell */
  align-items: center;    /* each item in the middle of its row */
  gap: 8px 16px;
  padding: 12px;
  border: 2px dashed #a1a1aa;
}

.cell {
  padding: 6px 10px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 4px;
}

.tall {
  padding: 18px 10px;
}
